-- ============================================================
-- Quantum Lab — email subscription (consent record) schema
--
-- Run this in the Supabase SQL editor AFTER schema.sql. Everything
-- here is OPTIONAL in the sense that the app boots without it: with
-- no SUPABASE_SERVICE_ROLE_KEY the subscription store falls back to
-- a Map in the Node process (apps/web/lib/email/subscriptions.ts).
-- That fallback keeps the flow demoable end-to-end and it does NOT
-- survive a restart — which for a CONSENT record means the durable
-- backend is not optional in any deployment that actually sends:
-- an opt-out that evaporates on redeploy is a broken promise, so
-- automated sending stays off until this table exists for real
-- (docs/ONBOARDING.md, "Email: nothing is sent, on purpose").
--
-- ############################################################
-- #  THIS TABLE IS WRITTEN AND READ ONLY BY THE SERVICE ROLE.#
-- #                                                          #
-- #  It is a list of email addresses. An authenticated       #
-- #  SELECT policy would hand any signed-in user every       #
-- #  subscriber's address — a breach, full stop. An INSERT   #
-- #  or UPDATE policy would let a client fabricate consent   #
-- #  ("this address asked for mail") or erase an opt-out,    #
-- #  which are the two lies this table exists to make        #
-- #  impossible.                                             #
-- #                                                          #
-- #  So RLS is enabled and NO POLICY IS CREATED. With RLS on #
-- #  and no policy, the anon and authenticated roles can do  #
-- #  nothing at all; the service role bypasses RLS and is    #
-- #  the only path in. Do not "fix" the missing policies.    #
-- #  Signups, confirmations and unsubscribes all go through  #
-- #  the route handlers in apps/web/app/api/email/, which    #
-- #  hold the service role and enforce the state machine.    #
-- ############################################################
--
-- HONESTY NOTE, same as schema-billing.sql, schema-orgs.sql and
-- schema-exams.sql: this file has never been run against a live
-- Supabase project. The shapes match what
-- apps/web/lib/email/subscriptions.ts reads and writes, and that
-- mapping is covered by tests against the in-memory double, but the
-- SQL itself is unverified. Check it before trusting it.
-- ============================================================

-- ── Subscriptions ────────────────────────────────────────────
-- One row per (address, purpose). This row IS the consent record:
-- consented_at is when the address was submitted, confirmed_at is
-- when its owner clicked the link mailed TO that address (double
-- opt-in — the submission alone proves nothing, anyone can type
-- anyone's address into a form), and unsubscribed_at is the opt-out
-- that every future send must honour FIRST. A sender may mail an
-- address only when confirmed_at is set and unsubscribed_at is not.
create table if not exists public.email_subscriptions (
  id              text primary key,

  -- Lower-cased before storage so one mailbox cannot hold several
  -- rows under case variants of itself.
  email           text not null check (char_length(email) <= 254),

  -- What was consented TO. Consent to a 7-day course is not consent
  -- to anything else; a new mailing needs a new purpose and a new
  -- opt-in, never a reuse of this list.
  purpose         text not null check (purpose in ('course-7day')),

  -- SHA-256 hex of the confirm/unsubscribe token. The token itself
  -- is never stored: it lives only in the two links mailed to the
  -- address, so a dump of this table contains no usable link and
  -- cannot be used to unsubscribe (or worse, "confirm") anyone.
  token_hash      text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),

  consented_at    timestamptz not null default now(),
  confirmed_at    timestamptz,
  unsubscribed_at timestamptz,

  created_at      timestamptz not null default now(),

  -- One row per mailbox per purpose. A re-signup updates the row
  -- (new token, new consented_at, confirmation reset) rather than
  -- stacking rows whose opt-out states could disagree.
  constraint email_subscriptions_one_per_purpose unique (email, purpose)
);

comment on table public.email_subscriptions is
  'Consent records for opt-in email. Service-role only: a client-writable consent row is a fabricated consent row. Sendable = confirmed_at set AND unsubscribed_at null.';
comment on column public.email_subscriptions.token_hash is
  'SHA-256 of the confirm/unsubscribe token. The token appears only in mailed links; the table never holds a usable secret.';
comment on column public.email_subscriptions.unsubscribed_at is
  'The opt-out. Any future sender must filter on this BEFORE building a batch; it is never cleared except by a fresh double-opt-in signup.';

-- The unsubscribe and confirm routes look a token hash up; the
-- unique constraint above already indexes token_hash. This one
-- serves the signup path's "does this mailbox already have a row?".
create index if not exists email_subscriptions_email_idx
  on public.email_subscriptions (email, purpose);

-- ── Row level security ───────────────────────────────────────
-- Enabled with NO policies, deliberately. See the banner at the top
-- of this file before changing anything here.
alter table public.email_subscriptions enable row level security;

-- ── 2026-08-25: the scheduler's send record ──────────────────
-- Added with the dispatch endpoint (apps/web/app/api/email/dispatch).
-- `add column if not exists` so this file stays re-runnable against
-- a project that already has the original table.
--
-- sent_days is the idempotency record: course day N is appended
-- BEFORE the message is handed to the provider, under a guard that
-- refuses the append if N is already present (see claimDay in
-- apps/web/lib/email/courseDispatch.ts). A crashed or concurrent
-- dispatch run can therefore drop a message (at-most-once) but can
-- never send the same day twice — the right failure direction for
-- unsolicited-feeling mail.
alter table public.email_subscriptions
  add column if not exists sent_days int[] not null default '{}';

-- The unsubscribe credential for COURSE mails, minted by the
-- dispatcher on the first send. Stored as plaintext, which is a
-- deliberate, narrower exception to the hash-only rule in the
-- banner above, with eyes open about what a leaked dump could do:
--   • token_hash (confirm + original unsubscribe) stays hash-only —
--     a dump still cannot fabricate consent or forge a confirm.
--   • this column exists BECAUSE the token behind token_hash is
--     never stored: the dispatcher has nothing it could put behind
--     the unsubscribe link every course mail must carry. A leaked
--     dump of this column lets someone unsubscribe subscribers — a
--     nuisance, and strictly less power than the UPDATE access any
--     dump-capable attacker already had. It cannot subscribe,
--     confirm, or read anything it does not itself contain.
--   • the alternative (deriving the token from a server secret)
--     silently breaks every already-mailed unsubscribe link the day
--     the secret rotates, which is worse than the nuisance.
-- The same token is reused for all seven days, so the link in day 2
-- still works when day 6 arrives.
alter table public.email_subscriptions
  add column if not exists course_unsubscribe_token text
    check (course_unsubscribe_token is null
           or course_unsubscribe_token ~ '^[0-9a-f]{64}$');

create unique index if not exists email_subscriptions_course_unsub_idx
  on public.email_subscriptions (course_unsubscribe_token)
  where course_unsubscribe_token is not null;

comment on column public.email_subscriptions.sent_days is
  'Course days (1-7) already claimed for sending. Appended atomically before the provider is called; a day in this array is never sent again.';
comment on column public.email_subscriptions.course_unsubscribe_token is
  'Plaintext unsubscribe token carried by course mails (GET /api/email/unsubscribe/course?token=…). Unsubscribe-only power; see the comment block above before "fixing" it into a hash.';
